# R/testing/test_S1.3d.R — S1.3d (BL-084): C-1 test unitari dei wrapper su casi con risposta analitica + comparatori + I/O.
# Uso (root del repo): R_LIBS_SITE=/nonexistent R_LIBS_USER=/nonexistent Rscript --vanilla R/testing/test_S1.3d.R   (PASS/FAIL per asserzione)
.libPaths("renv/library/linux-ubuntu-noble/R-4.6/x86_64-pc-linux-gnu")
source("tools/S1.3d_common.R"); source("tools/S1.3d_candidates.R"); source("tools/S1.3d_f4.R"); source("tools/S1.3d_compare.R"); source("tools/S1.3d_cases.R")
R <- list(); chk <- function(case, what, cand, ok, val = "") { R[[length(R) + 1]] <<- data.frame(case = case, what = what, cand = cand, ok = isTRUE(ok), value = as.character(val))
  cat(sprintf("%s  %-14s %-34s %-3s %s\n", if (isTRUE(ok)) "PASS" else "FAIL", case, what, cand, val)) }
near <- function(a, b, tol = 1e-9) isTRUE(abs(a - b) <= tol)
# T1: due quadrati adiacenti in una regione 2x1 (unione 2, diff. simmetrica 0, coppia 0); T2: sovrapposti di 0.5 (coppia 0.5, unione 1.5)
T1 <- list(terr = st_sfc(sq(1000, 0, 1001, 1), sq(1001, 0, 1002, 1)), reg = st_sfc(sq(1000, 0, 1002, 1)))
T2 <- list(terr = st_sfc(sq(1000, 0, 1001, 1), sq(1000.5, 0, 1001.5, 1)), reg = st_sfc(sq(1000, 0, 1001.5, 1)))
h <- rbind(c(1003, 1003), c(1003, 1007), c(1007, 1007), c(1007, 1003))
T3 <- list(terr = st_sfc(pg(rbind(c(1000, 1000), c(1010, 1000), c(1010, 1010), c(1000, 1010)), list(h)), sq(1003, 1003, 1007, 1007)), reg = st_sfc(sq(1000, 1000, 1010, 1010)))
for (cd in setdiff(CANDS_O1, "F4")) {
  o <- o1_run(cand_prepare(cd, T1$terr, T1$reg), matrix(c(1L, 2L), 1))
  chk("T1 adiacenti", "unione = 2", cd, near(o$union_a, 2), o$union_a); chk("T1 adiacenti", "diff. simmetrica = 0", cd, near(o$symd_a, 0), o$symd_a)
  chk("T1 adiacenti", "coppia (i,j) e (j,i) = 0", cd, near(o$pij, 0) && near(o$pji, 0), paste(o$pij, o$pji))
  o <- o1_run(cand_prepare(cd, T2$terr, T2$reg), matrix(c(1L, 2L), 1))
  chk("T2 sovrapposti", "coppia = 0.5 nei due ordini", cd, near(o$pij, 0.5) && near(o$pji, 0.5), paste(o$pij, o$pji)); chk("T2 sovrapposti", "unione = 1.5", cd, near(o$union_a, 1.5), o$union_a)
  o <- o1_run(cand_prepare(cd, T3$terr, T3$reg), matrix(c(1L, 2L), 1))
  chk("T3 buco", "aree 84 e 16", cd, near(o$area[1], 84) && near(o$area[2], 16), paste(o$area, collapse = " ")); chk("T3 buco", "unione = 100", cd, near(o$union_a, 100), o$union_a)
  chk("T3 buco", "coppia = 0", cd, near(o$pij, 0) && near(o$pji, 0), paste(o$pij, o$pji))
}
# O2: quadrato [1001,1003]^2 su bin da 2 µm -> 4 pezzi da 1 µm²; triangolo (1000,1000),(1004,1000),(1000,1004) -> 8 µm² in tutto
gsq <- list(terr = st_sfc(sq(1001, 1001, 1003, 1003), pg(rbind(c(1000, 1000), c(1004, 1000), c(1000, 1004)))))
gs <- grid_spec(st_bbox(gsq$terr))
for (cd in setdiff(CANDS_O2, "F4")) {
  C <- cand_prepare(cd, gsq$terr, st_sfc(sq(1000, 1000, 1004, 1004))); o <- o2_run(C, gs, 2); p <- o$pieces
  p1 <- p[p$i == 1, ]; chk("O2 quadrato", "4 pezzi da 1 µm²", cd, nrow(p1) == 4 && all(abs(p1$area - 1) < 1e-9), paste(round(p1$area, 12), collapse = " "))
  chk("O2 quadrato", "bin (0,0),(1,0),(0,1),(1,1)", cd, setequal(paste(p1$ix, p1$iy), c("0 0", "1 0", "0 1", "1 1")), paste(p1$ix, p1$iy, collapse = ";"))
  p2 <- p[p$i == 2, ]; chk("O2 triangolo", "somma 8, bin interno (0,0) = 4", cd, near(sum(p2$area), 8) && near(p2$area[p2$ix == 0 & p2$iy == 0], 4), sum(p2$area))
  o8 <- o2_run(C, gs, 8); a3 <- o3_aggregate(p); m3 <- merge(a3, o8$pieces, by = c("i", "ix", "iy"))
  chk("O3", "aggregato 2->8 = diretto 8", cd, nrow(m3) == nrow(o8$pieces) && all(abs(m3$area.x - m3$area.y) < 1e-9), nrow(m3))
}
# I/O bit-esatto (buco e multipoligono)
mp <- st_multipolygon(list(unclass(sq(0, 0, 1, 1)), unclass(sq(2, 0, 3, 1)))); io <- st_sfc(T3$terr[[1]], mp, sq(pi, exp(1), pi + 1, exp(1) + 1))
chk("I/O", "geom_to_df/df_to_sfc bit-esatto", "-", identical(st_as_binary(df_to_sfc(geom_to_df(io), 3)), st_as_binary(io)))
# comparatori: errore piantato rilevato, identità accettata
tr <- list(union = 2, symd = 0); tp <- data.frame(i = 1L, j = 2L, a = 0); tc <- data.frame(a = c(1, 1)); P <- c(4, 4)
o <- list(cand = "X", area = c(1, 1), union_a = 2, symd_a = 0, pij = 0, pji = 0, errors = character(0), n_pair_err = 0, time = c(prepare = 0, union = 0, pairs = 0))
chk("cmp_o1", "identità -> nessun FAIL", "-", !cmp_o1(o, tr, tp, tc, P, 6)$summary$fail)
o2 <- o; o2$union_a <- 2 - 2 * 1e-6 * 14; chk("cmp_o1", "unione -2 tau -> FAIL", "-", cmp_o1(o2, tr, tp, tc, P, 6)$summary$union_viol)
o2 <- o; o2$pji <- 1e-4; chk("cmp_o1", "coppia (j,i) 1e-4 -> FAIL", "-", cmp_o1(o2, tr, tp, tc, P, 6)$summary$pair_viol_ji == 1)
o2 <- o; o2$errors <- c(union = "x"); chk("cmp_o1", "eccezione -> FAIL non silenzioso", "-", with(cmp_o1(o2, tr, tp, tc, P, 6)$summary, fail && !silent))
t2 <- data.frame(i = c(1L, 1L), ix = c(0L, 1L), iy = c(0L, 0L), area = c(1, 1), perim = c(4, 4))
chk("cmp_o2", "identità -> 0 violazioni", "-", cmp_o2(transform(t2), t2, 2, "X")$summary$n_viol == 0)
chk("cmp_o2", "pezzo mancante -> 1 mancante", "-", cmp_o2(t2[1, ], t2, 2, "X")$summary$n_missing == 1)
chk("cmp_o2", "id 100000 double vs intero -> stessa chiave (D-3)", "-", cmp_o2(transform(t2, i = c(1e5, 1e5)), transform(t2, i = c(100000L, 100000L)), 2, "X")$summary$n_viol == 0)
chk("cmp_o2", "pezzo spurio -> 1 spurio", "-", cmp_o2(rbind(t2, data.frame(i = 2L, ix = 0L, iy = 0L, area = 0.5, perim = 3)), t2, 2, "X")$summary$n_spurious == 1)
# F4 su un caso piccolo: stesse aree di tessellate_voronoi entro tau, copertura con vertici condivisi identici (verifica in python a parte)
set.seed(7); x <- 1000 + runif(60, 0, 20); y <- 1000 + runif(60, 0, 20); rg <- pg(rbind(c(1000, 1000), c(1020, 1000), c(1020, 1013.3), c(1011.1, 1020), c(1000, 1020)))
cen <- data.frame(cell_id = 1:60, region_id = 1L, x = x, y = y)
inr <- lengths(st_intersects(st_as_sfc(lapply(1:60, function(k) st_point(c(x[k], y[k])))), st_sfc(rg))) > 0; cen <- cen[inr, ]; cen$cell_id <- seq_len(nrow(cen))
tv <- tessellate_voronoi(cen, list(region_df = data.frame(region_id = 1L, cluster_id = 1L, area_um2 = as.numeric(st_area(st_sfc(rg)))), region_polygons = st_sfc(rg)), verbose = FALSE)
b <- f4_build(cen$x, cen$y, st_sfc(rg)); d <- abs(as.numeric(st_area(b$terr)) - tv$territory_df$territory_area)
chk("F4 piccolo", "|Δa| <= g*P per tutte le celle", "F4", all(d <= 1e-6 * s3b_perim(tv$cell_territories)), max(d))
chk("F4 piccolo", "0 invalide, 0 vuote, 0 ambigue", "F4", b$info$n_invalid == 0 && b$info$n_empty == 0 && b$info$n_ambiguous == 0)
chk("F4 piccolo", "frammenti come 04b3", "F4", identical(as.integer(b$info$lost), as.integer(tv$territory_df$n_pieces_lost)) && identical(as.integer(b$info$gained), as.integer(tv$territory_df$n_pieces_gained)))
chk("ulp", "ulp1(0) = 2^-1074 (perturbazione di uno zero cambia l'input)", "-", ulp1(0) == 2^-1074 && (0 + ulp1(0)) != 0, ulp1(0))
# u4: la coppia a cavallo si arrotonda davvero a nodi diversi (BL-083)
xx <- u4_pair((1000e6 + 0.5) / 1e6); chk("u4", "xL, xR arrotondati a nodi diversi", "-", round(xx[1] / 1e-6) != round(xx[2] / 1e-6), paste(sprintf("%.17g", xx[1:2]), collapse = " "))
# F2: scheggia da 1e-7 µm che collassa all'arrotondamento -> nessuna eccezione, cella vuota (area 0 <= tau_i)
cs <- u3_cases(); s <- cs[[which(vapply(cs, `[[`, "", "key") == "U3_sliver")]]
o <- tryCatch(o1_run(cand_prepare("F2", s$terr, s$reg), matrix(c(1L, 2L, 2L, 3L), 2, byrow = TRUE)), error = function(e) conditionMessage(e))
chk("F2 collasso", "nessuna eccezione; cella 2 vuota", "F2", is.list(o) && length(o$errors) == 0 && o$area[2] == 0, if (is.list(o)) o$area[2] else o)
R <- do.call(rbind, R); dir.create("results/S1.3d", showWarnings = FALSE); write.csv(R, "results/S1.3d/S1.3d_test.csv", row.names = FALSE)
cat(sprintf("\nC-1: %d/%d PASS\n", sum(R$ok), nrow(R))); if (!all(R$ok)) quit(status = 1)
